      },
      "OpenUploads": {
        "type": "object",
        "description": "Multipart uploads started and not yet completed or aborted.",
        "required": [
          "count",
          "limit"
        ],
        "properties": {
          "count": {
            "type": "integer",
            "minimum": 0,
            "format": "int64"
          },
          "limit": {
            "type": "integer",
            "minimum": 0,
            "format": "int64"
          }
        }
      },
      "UsageDay": {
        "type": "object",
        "required": [
          "day",
          "status",
          "peak_stored_bytes",
          "uploaded_bytes",
          "downloaded_bytes",
          "requests_approx"
        ],
        "properties": {
          "day": {
            "type": "string",
            "format": "date"
          },
          "status": {
            "type": "string",
            "enum": [
              "provisional",
              "final",
              "under_review"
            ]
          },
          "peak_stored_bytes": {
            "type": "integer",
            "minimum": 0,
            "format": "int64"
          },
          "uploaded_bytes": {
            "type": "integer",
            "minimum": 0,
            "format": "int64"
          },
          "downloaded_bytes": {
            "type": "integer",
            "minimum": 0,
            "format": "int64"
          },
          "requests_approx": {
            "type": "integer",
            "minimum": 0,
            "description": "Approximate number of S3 requests that day.",
            "format": "int64"
          }
        }
      },
      "UsageDayList": {
        "type": "object",
        "required": [
          "data",
          "next_cursor"
        ],
        "properties": {
          "data": {
            "type": "array",
            "items": {
              "$ref": "#/components/schemas/UsageDay"
            }
          },
          "next_cursor": {
            "oneOf": [
              {
                "$ref": "#/components/schemas/Cursor"
              },
              {
                "type": "null"
              }
            ]
          }
        }
      },
      "BucketUsage": {
        "type": "object",
        "required": [
          "bucket",
          "stored_bytes",
          "object_count",
          "as_of"
        ],
        "properties": {
          "bucket": {
            "$ref": "#/components/schemas/BucketName"
          },
          "stored_bytes": {
            "type": "integer",
            "minimum": 0,
            "format": "int64"
          },
          "object_count": {
            "type": "integer",
            "minimum": 0,
            "format": "int64"
          },
          "as_of": {
            "$ref": "#/components/schemas/Timestamp"
          }
        }
      },
      "BucketUsageList": {
        "type": "object",
        "required": [
          "data",
          "next_cursor"
        ],
        "properties": {
          "data": {
            "type": "array",
            "items": {
              "$ref": "#/components/schemas/BucketUsage"
            }
          },
          "next_cursor": {
            "oneOf": [
              {
                "$ref": "#/components/schemas/Cursor"
              },
              {
                "type": "null"
              }
            ]
          }
        }
      },
      "Event": {
        "type": "object",
        "required": [
          "id",
          "type",
          "created_at",
          "data"
        ],
        "properties": {
          "id": {
            "type": "string",
            "pattern": "^evt_[a-z0-9]{1,64}$"
          },
          "type": {
            "type": "string",
            "pattern": "^[a-z_]+(\\.[a-z_]+)+$",
            "description": "`resource.verb_past`, for example `key.created`."
          },
          "created_at": {
            "$ref": "#/components/schemas/Timestamp"
          },
          "data": {
            "type": "object",
            "description": "Event-specific fields. Never holds a secret.",
            "additionalProperties": true
          }
        }
      },
      "EventList": {
        "type": "object",
        "required": [
          "data",
          "next_cursor"
        ],
        "properties": {
          "data": {
            "type": "array",
            "items": {
              "$ref": "#/components/schemas/Event"
            }
          },
          "next_cursor": {
            "allOf": [
              {
                "$ref": "#/components/schemas/Cursor"
              }
            ],
            "description": "The position to continue from. Never `null` for the feed."
          }
        }
      },
      "PresignRequest": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "bucket",
          "key",
          "method"
        ],
        "properties": {
          "bucket": {
            "$ref": "#/components/schemas/BucketName"
          },
          "key": {
            "type": "string",
            "minLength": 1,
            "maxLength": 1024,
            "description": "The object key."
          },
          "method": {
            "type": "string",
            "enum": [
              "GET"
            ],
            "description": "Only downloads are offered for now."
          },
          "expires_in_seconds": {
            "$ref": "#/components/schemas/PresignLifetime",
            "default": 900
          }
        }
      },
      "PresignLifetime": {
        "type": "integer",
        "minimum": 1,
        "maximum": 900,
        "default": 900,
        "description": "How long the URL stays valid, in seconds, 1 to 900 (15 minutes). Default 900."
      },
      "PresignedUrl": {
        "type": "object",
        "required": [
          "method",
          "url",
          "expires_at"
        ],
        "properties": {
          "method": {
            "type": "string",
            "enum": [
              "GET"
            ]
          },
          "url": {
            "type": "string",
            "format": "uri"
          },
          "expires_at": {
            "$ref": "#/components/schemas/Timestamp"
          }
        }
      },
      "Problem": {
        "type": "object",
        "description": "RFC 9457 problem details with Kofra's fields. Only `code` is stable.",
        "required": [
          "type",
          "title",
          "status",
          "code",
          "detail",
          "hint",
          "docs_url",
          "request_id",
          "retryable"
        ],
        "properties": {
          "type": {
            "type": "string",
            "format": "uri",
            "description": "A page describing this error code."
          },
          "title": {
            "type": "string"
          },
          "status": {
            "type": "integer",
            "minimum": 400,
            "maximum": 599
          },
          "code": {
            "type": "string",
            "pattern": "^[a-z][a-z0-9_]*$",
            "description": "Stable machine name; see the error catalogue. New codes may be added within `/v1`."
          },
          "detail": {
            "type": "string"
          },
          "hint": {
            "type": "string",
            "description": "What to do next, in one sentence."
          },
          "docs_url": {
            "type": "string",
            "format": "uri",
            "description": "The Markdown version of the error page."
          },
          "request_id": {
            "type": "string",
            "description": "Same as the `Kofra-Request-Id` header. Quote it to support."
          },
          "retryable": {
            "type": "boolean",
            "description": "Whether the same request may succeed if repeated (after `Retry-After`, when given)."
          },
          "errors": {
            "type": "array",
            "description": "Per-field problems, for `validation_failed`, `unknown_field` and similar codes.",
            "items": {
              "$ref": "#/components/schemas/FieldError"
            }
          }
        }
      },
      "FieldError": {
        "type": "object",
        "required": [
          "pointer",
          "code",
          "detail"
        ],
        "properties": {
          "pointer": {
            "type": "string",
            "description": "JSON pointer to the field (RFC 6901), or `#query/<name>`, `#path/<name>` or `#header/<name>` for parameters."
          },
          "code": {
            "type": "string"
          },
          "detail": {
            "type": "string"
          }
        }
      }
    },
    "headers": {
      "KofraRequestId": {
        "description": "Unique ID of this request. The same ID is in the error body and the audit log; quote it to support.",
        "schema": {
          "type": "string"
        },
        "example": "req_01jd3examplerequestid0000"
      },
      "RateLimit": {
        "description": "Remaining allowance of the policy that applies (draft-ietf-httpapi-ratelimit-headers).",
        "schema": {
          "type": "string"
        },
        "example": "\"default\";r=49;t=1"
      },
      "RateLimitPolicy": {
        "description": "The rate-limit policies that apply to this credential (draft-ietf-httpapi-ratelimit-headers).",
        "schema": {
          "type": "string"
        },
        "example": "\"default\";q=50;w=1, \"writes\";q=2;w=1"
      },
      "RetryAfter": {
        "description": "Seconds to wait before retrying.",
        "schema": {
          "type": "integer",
          "minimum": 0
        },
        "example": 2
      },
      "WWWAuthenticate": {
        "description": "The authentication challenge (RFC 6750): `Bearer realm=\"kofra\"`, with `error=\"invalid_token\"` when a token was sent but is not usable.",
        "schema": {
          "type": "string"
        },
        "example": "Bearer realm=\"kofra\", error=\"invalid_token\""
      },
      "Link": {
        "description": "The next page, as `<url>; rel=\"next\"`, while more follow.",
        "schema": {
          "type": "string"
        },
        "example": "</v1/buckets?cursor=c_2Xk9>; rel=\"next\""
      }
    }
  }
}

discovery.mcpJson:
{
	"name": "Kofra",
	"description": "Model Context Protocol servers for Kofra.",
	"servers": [
		{
			"name": "kofra-docs",
			"title": "Kofra documentation",
			"description": "Search and read the Kofra API documentation, API reference and error catalogue. No login and no account data.",
			"url": "https://mcp.kofra.app/docs",
			"transport": "streamable-http",
			"authentication": "none"
		}
	]
}
